#!/usr/bin/env python3
"""Turn the structured tag table (JSON, derived from observed CLI output) into
a C++ data table compiled into our binary."""
import json, sys

def cstr(s):
    out = []
    for ch in s:
        if ch == '\\': out.append('\\\\')
        elif ch == '"': out.append('\\"')
        elif ch == '\t': out.append('\\t')
        elif ch == '\n': out.append('\\n')
        elif ch == '?': out.append('\\?')
        else: out.append(ch)
    return '"' + ''.join(out) + '"'

def emit(d, out):
    w = out.write
    w('// Generated by tools/gen_configdata.py from behaviour observed through\n')
    w('// the reference tool\'s command line interface.  Do not edit by hand.\n')
    w('#include "configdata.h"\n\nnamespace configdata {\n\n')

    tags = [x for x in d['items'] if x['kind'] == 'tag']

    # doc line pools
    for t in tags:
        if t['doc']:
            w('static const char *doc_%s[] = {' % t['name'])
            w(','.join(cstr(l) for l in t['doc']))
            w('};\n')
    w('\n')
    for t in tags:
        if t['default']:
            w('static const char *def_%s[] = {' % t['name'])
            w(','.join(cstr(l) for l in t['default']))
            w('};\n')
    w('\n')
    for t in tags:
        if t['type'] == 'enum':
            w('static const char *enum_%s[] = {' % t['name'])
            w(','.join(cstr(l) for l in t['values']))
            w('};\n')
    w('\n')

    w('const char *headerLines[] = {\n')
    for l in d['header']:
        w('  %s,\n' % cstr(l))
    w('};\n')
    w('const int numHeaderLines = %d;\n\n' % len(d['header']))

    w('const Entry entries[] = {\n')
    for it in d['items']:
        if it['kind'] == 'section':
            w('  { Kind::Section, %s, Type::Bool, nullptr,0, nullptr,0, nullptr,0, 0,0 },\n'
              % cstr(it['title']))
        else:
            n = it['name']
            ty = {'bool':'Bool','string':'String','list':'List','int':'Int','enum':'Enum'}[it['type']]
            doc = ('doc_%s,%d' % (n, len(it['doc']))) if it['doc'] else 'nullptr,0'
            dfl = ('def_%s,%d' % (n, len(it['default']))) if it['default'] else 'nullptr,0'
            en  = ('enum_%s,%d' % (n, len(it['values']))) if it['type'] == 'enum' else 'nullptr,0'
            mn, mx = it.get('min', 0), it.get('max', 0)
            w('  { Kind::Tag, %s, Type::%s, %s, %s, %s, %d,%d },\n'
              % (cstr(n), ty, doc, dfl, en, mn, mx))
    w('};\n')
    w('const int numEntries = %d;\n\n' % len(d['items']))
    w('} // namespace configdata\n')

if __name__ == '__main__':
    d = json.load(open(sys.argv[1]))
    with open(sys.argv[2], 'w') as f:
        emit(d, f)
    print('wrote', sys.argv[2])
PYEOF
echo ok

