 *
 * The table itself lives in the generated configdata.cpp; it was built by
 * observing the reference implementation through its command line interface
 * (see tools/gen_configdata.py).
 */
#ifndef CONFIGDATA_H
#define CONFIGDATA_H

namespace configdata {

enum class Kind { Section, Tag };
enum class Type { Bool, String, List, Int, Enum };

struct Entry
{
  Kind kind;
  const char *name;      //!< tag name, or section title when kind==Section
  Type type;
  const char *const *doc;
  int numDoc;
  const char *const *defaults;
  int numDefaults;
  const char *const *enumValues;
  int numEnumValues;
  int minVal;
  int maxVal;
};

extern const Entry entries[];
extern const int numEntries;
extern const char *headerLines[];
extern const int numHeaderLines;

/*! Tags that older versions understood but that no longer have any effect. */
extern const char *const obsoleteTags[];
extern const int numObsoleteTags;

} // namespace configdata

#endif

