#!/usr/bin/env python3
"""Third sweep: 3-word candidates built from real prefixes/suffixes."""
import json, subprocess, os, re, tempfile
BIN='/workspace/executable'; cwd=tempfile.mkdtemp()
d=json.load(open('cfg2.json'))
known={x['name'] for x in d['items'] if x['kind']=='tag'}
found=set(json.load(open('obsolete.json')))
allnames=known|found
vocab=set()
for n in allnames:
    for w in n.split('_'): vocab.add(w)
pre2=set(); suf2=set()
for n in allnames:
    p=n.split('_')
    for i in range(len(p)-1):
        pre2.add('_'.join(p[:i+2]) if i==0 else None)
    if len(p)>=2:
        pre2.add(p[0]+'_'+p[1]); suf2.add(p[-2]+'_'+p[-1])
pre2={x for x in pre2 if x}
V=sorted(vocab)
cands=set()
for p in sorted(pre2):
    for w in V: cands.add(p+'_'+w)
for s in sorted(suf2):
    for w in V: cands.add(w+'_'+s)
for p in sorted(pre2):
    for s in sorted(suf2): cands.add(p+'_'+s)
cands -= allnames
cands=sorted(cands)
print('candidates', len(cands), flush=True)
def classify(batch):
    open(os.path.join(cwd,'P'),'w').write(''.join('%s = 1\n'%n for n in batch))
    r=subprocess.run([BIN,'-x','P'],cwd=cwd,capture_output=True,text=True)
    return set(re.findall(r"Tag '([A-Z_0-9]+)' at line \d+ of file 'P' has become obsolete", r.stdout+r.stderr))
B=400
for i in range(0,len(cands),B):
    n=classify(cands[i:i+B])
    if n-found: print('NEW', sorted(n-found), flush=True)
    found|=n
print('total', len(found))
json.dump(sorted(found), open('obsolete.json','w'), indent=1)
PYEOF
