#!/usr/bin/env python3
"""Find tags the tool accepts but does not emit in its own template (-g)."""
import json, subprocess, os, re, tempfile, sys
BIN='/workspace/executable'; cwd=tempfile.mkdtemp()
d=json.load(open('cfg2.json'))
known={x['name'] for x in d['items'] if x['kind']=='tag'}
obs=set(json.load(open('obsolete.json')))
allnames=known|obs
vocab=set()
for n in allnames:
    for w in n.split('_'): vocab.add(w)
extra={'HUE','SAT','SATURATION','GAMMA','COLORSTYLE','SEARCHENGINE','HTAGS','ANONYMOUS',
       'BRIEFDESC','FILEVERSION','SMART','REFS','CROSS','ELAPSED','FONT','FONTNAME','FONTSIZE',
       'FONTPATH','LOOK','UML','LIMIT','WIDTH','HEIGHT','DEPTH','TRANSPARENT','MULTI','TARGETS'}
vocab|=extra
V=sorted(v for v in vocab if v)
pre=set(); suf=set()
for n in allnames:
    p=n.split('_')
    for i in range(1,len(p)):
        pre.add('_'.join(p[:i])); suf.add('_'.join(p[i:]))
cands=set()
for a in V:
    for b in V: cands.add(a+'_'+b)
for p in sorted(pre):
    for w in V: cands.add(p+'_'+w)
for s in sorted(suf):
    for w in V: cands.add(w+'_'+s)
cands|=set(V)
cands -= allnames
cands=sorted(cands)
print('candidates', len(cands), flush=True)
def classify(batch):
    open(os.path.join(cwd,'P'),'w').write(''.join('%s = 1\n'%n for n in batch))
    r=subprocess.run([BIN,'-x','P'],cwd=cwd,capture_output=True,text=True)
    out=r.stdout+r.stderr
    unsup=set(re.findall(r"ignoring unsupported tag '([A-Z_0-9]+)'", out))
    ob=set(re.findall(r"Tag '([A-Z_0-9]+)' at line \d+ of file 'P' has become obsolete", out))
    return set(batch)-unsup-ob, ob
hidden=set()
B=300
for i in range(0,len(cands),B):
    h,o=classify(cands[i:i+B])
    if h: print('HIDDEN', sorted(h), flush=True)
    if o-obs: print('OBS-NEW', sorted(o-obs), flush=True)
    hidden|=h; obs|=o
json.dump(sorted(hidden), open('hidden.json','w'), indent=1)
json.dump(sorted(obs), open('obsolete.json','w'), indent=1)
print('hidden', len(hidden), 'obsolete', len(obs))
PYEOF
