#include "message.h"
#include "version.h"

#include <cstdarg>
#include <cstdio>
#include <cstdlib>
#include <string>

const char *fullVersionString()
{
  static std::string s = std::string(TOOL_VERSION) + " (" + TOOL_COMMIT + ")";
  return s.c_str();
}

static bool  g_quiet    = false;
static bool  g_warnings = true;
static FILE *g_warnFile = nullptr;   // nullptr => stderr
static int   g_warnCount = 0;

void setQuiet(bool q)            { g_quiet = q; }
bool isQuiet()                   { return g_quiet; }
void setWarningsEnabled(bool e)  { g_warnings = e; }
int  warningCount()              { return g_warnCount; }

void setWarnLogFile(const std::string &f)
{
  if (f.empty()) return;
  if (f == "-")  { g_warnFile = stdout; return; }
  if (f == "stdout") { g_warnFile = stdout; return; }
  if (f == "stderr") { g_warnFile = stderr; return; }
  g_warnFile = fopen(f.c_str(), "w");
}

void closeWarnLogFile()
{
  if (g_warnFile && g_warnFile != stdout && g_warnFile != stderr)
  {
    fclose(g_warnFile);
  }
  g_warnFile = nullptr;
}

static FILE *warnTarget()
{
  return g_warnFile ? g_warnFile : stderr;
}

static std::string vformat(const char *fmt, va_list args)
{
  va_list copy;
  va_copy(copy, args);
  int n = vsnprintf(nullptr, 0, fmt, copy);
  va_end(copy);
  if (n < 0) return std::string();
  std::string out(static_cast<size_t>(n), '\0');
  vsnprintf(&out[0], static_cast<size_t>(n) + 1, fmt, args);
  return out;
}

void msg(const char *fmt, ...)
{
  if (g_quiet) return;
  va_list args; va_start(args, fmt);
  std::string s = vformat(fmt, args);
  va_end(args);
  fputs(s.c_str(), stdout);
  fflush(stdout);
}

void err(const char *fmt, ...)
{
  va_list args; va_start(args, fmt);
  std::string s = vformat(fmt, args);
  va_end(args);
  fprintf(warnTarget(), "error: %s", s.c_str());
  fflush(warnTarget());
}

void errNoPrefix(const char *fmt, ...)
{
  va_list args; va_start(args, fmt);
  std::string s = vformat(fmt, args);
  va_end(args);
  fputs(s.c_str(), warnTarget());
  fflush(warnTarget());
}

void term(const char *fmt, ...)
{
  va_list args; va_start(args, fmt);
  std::string s = vformat(fmt, args);
  va_end(args);
  fprintf(warnTarget(), "error: %s", s.c_str());
  fflush(warnTarget());
  closeWarnLogFile();
  exit(1);
}

void warn_uncond(const char *fmt, ...)
{
  va_list args; va_start(args, fmt);
  std::string s = vformat(fmt, args);
  va_end(args);
  g_warnCount++;
  fprintf(warnTarget(), "warning: %s", s.c_str());
  fflush(warnTarget());
}

void warn(const std::string &file, int line, const char *fmt, ...)
{
  if (!g_warnings) return;
  va_list args; va_start(args, fmt);
  std::string s = vformat(fmt, args);
  va_end(args);
  g_warnCount++;
  fprintf(warnTarget(), "%s:%d: warning: %s", file.c_str(), line, s.c_str());
  fflush(warnTarget());
}

