#ifndef CONFIG_H
#define CONFIG_H

#include <map>
#include <string>
#include <vector>

#include "configdata.h"

/*! Runtime representation of one configuration tag. */
struct ConfigTag
{
  std::string              name;
  configdata::Type         type = configdata::Type::String;
  std::string              value;      //!< for String / Enum
  bool                     bvalue = false;
  int                      ivalue = 0;
  std::vector<std::string> lvalue;     //!< for List
  bool                     userSet = false;
  const configdata::Entry *decl = nullptr;
};

class Config
{
  public:
    static Config &instance();

    /*! Reset every tag to its documented default. */
    void loadDefaults();

    /*! Parse a Doxyfile.  Returns false when the file cannot be read.
     *  \param fileName  name of the file, "-" reads standard input
     *  \param substEnv  replace $(VAR) references by environment values
     */
    bool parse(const std::string &fileName, bool substEnv);

    /*! Validate values, clamp out of range numbers and apply cross-tag rules. */
    void check();

    /*! Write the full template, optionally without the explanatory comments. */
    void writeTemplate(FILE *f, bool shortList, bool updateOnly) const;

    /*! Write only the tags whose value differs from the default. */
    void writeDifference(FILE *f) const;

    // ---- typed access -------------------------------------------------
    bool                            getBool(const std::string &n) const;
    int                             getInt(const std::string &n) const;
    const std::string              &getString(const std::string &n) const;
    const std::string              &getEnum(const std::string &n) const;
    const std::vector<std::string> &getList(const std::string &n) const;

    void setBool(const std::string &n, bool v);
    void setString(const std::string &n, const std::string &v);
    void setList(const std::string &n, const std::vector<std::string> &v);

    bool has(const std::string &n) const;

  private:
    Config() = default;

    ConfigTag       *find(const std::string &n);
    const ConfigTag *find(const std::string &n) const;

    bool parseString(const std::string &fileName, const std::string &data, bool substEnv);
    void assign(ConfigTag *t, const std::string &raw, bool append,
                const std::string &fileName, int line);

    std::vector<ConfigTag>              m_tags;
    std::map<std::string, size_t>       m_index;
    std::vector<std::string>            m_includePath;
};

/*! Convenience wrappers used throughout the generators. */
bool                            cfgBool(const char *n);
int                             cfgInt(const char *n);
const std::string              &cfgString(const char *n);
const std::string              &cfgEnum(const char *n);
const std::vector<std::string> &cfgList(const char *n);

/*! Format a value the way the template writer does (adds quotes if needed). */
std::string quoteConfigValue(const std::string &v);

#endif

