    /*! Validate values, clamp out of range numbers and apply cross-tag rules. */
    void check();

    /*! Write the full template, optionally without the explanatory comments. */
    void writeTemplate(FILE *f, bool shortList, bool updateOnly) const;

    /*! Write only the tags whose value differs from the default. */
    void writeDifference(FILE *f) const;

    // ---- typed access -------------------------------------------------
    bool                            getBool(const std::string &n) const;
