      {
        inQuote = false;
        // anything other than a separator after the closing quote is bad
        if (i + 1 < raw.size() && !strchr(" \t,", raw[i + 1])) bad = true;
      }
      continue;
    }
    if (!inQuote && (c == ' ' || c == '\t' || c == ',' || c == '\n'))
    {
      if (have) { res.push_back(cur); cur.clear(); have = false; quotedItem = false; }
      continue;
    }
    cur += c;
    have = true;
  }
  if (inQuote) bad = true;
  if (have) res.push_back(cur);
  wellQuoted = !bad;
  return res;
}

/*! Strip the optional surrounding quotes from a scalar value. */
static std::string unquoteScalar(const std::string &raw, bool &wellQuoted)
{
  wellQuoted = true;
  std::string v = trimWhiteSpace(raw);
  if (v.empty()) return v;
  if (v[0] != '"')
  {
    // a quote appearing later on is a quoting error
    if (v.find('"') != std::string::npos)
    {
      wellQuoted = false;
      std::string out;
      for (char c : v) if (c != '"') out += c;
      return out;
    }
    return v;
  }
  // starts with a quote: must be a single fully quoted token
  std::string out;
  bool closed = false;
  size_t i = 1;
  for (; i < v.size(); i++)
  {
    if (v[i] == '\\' && i + 1 < v.size() && v[i + 1] == '"') { out += '"'; i++; continue; }
    if (v[i] == '"') { closed = true; i++; break; }
    out += v[i];
  }
  if (!closed) { wellQuoted = false; return out; }
  if (i < v.size())
  {
    // trailing garbage after the closing quote
    wellQuoted = false;
    std::string rest = v.substr(i);
    for (char c : rest) if (c != '"') out += c;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

Config &Config::instance()
{
  static Config c;
  return c;
}

void Config::loadDefaults()
{
  m_tags.clear();
  m_index.clear();
  for (int i = 0; i < configdata::numEntries; i++)
  {
    const Entry &e = configdata::entries[i];
    if (e.kind != Kind::Tag) continue;
    ConfigTag t;
    t.name = e.name;
    t.type = e.type;
    t.decl = &e;
    switch (e.type)
    {
      case Type::Bool:
        t.bvalue = e.numDefaults > 0 && strcmp(e.defaults[0], "YES") == 0;
        break;
      case Type::Int:
        t.ivalue = e.numDefaults > 0 ? atoi(e.defaults[0]) : 0;
        break;
      case Type::String:
      case Type::Enum:
        t.value = e.numDefaults > 0 ? e.defaults[0] : "";
        break;
      case Type::List:
        for (int k = 0; k < e.numDefaults; k++) t.lvalue.push_back(e.defaults[k]);
        break;
    }
    m_index[t.name] = m_tags.size();
    m_tags.push_back(t);
  }
}

ConfigTag *Config::find(const std::string &n)
{
  auto it = m_index.find(n);
  return it == m_index.end() ? nullptr : &m_tags[it->second];
}

const ConfigTag *Config::find(const std::string &n) const
{
  auto it = m_index.find(n);
  return it == m_index.end() ? nullptr : &m_tags[it->second];
}

bool Config::has(const std::string &n) const { return find(n) != nullptr; }

bool Config::getBool(const std::string &n) const
{
  const ConfigTag *t = find(n);
  return t ? t->bvalue : false;
}

int Config::getInt(const std::string &n) const
{
  const ConfigTag *t = find(n);
  return t ? t->ivalue : 0;
}

static const std::string g_emptyString;
static const std::vector<std::string> g_emptyList;

const std::string &Config::getString(const std::string &n) const
{
  const ConfigTag *t = find(n);
  return t ? t->value : g_emptyString;
}

const std::string &Config::getEnum(const std::string &n) const { return getString(n); }

const std::vector<std::string> &Config::getList(const std::string &n) const
{
  const ConfigTag *t = find(n);
  return t ? t->lvalue : g_emptyList;
}

void Config::setBool(const std::string &n, bool v)
{
  ConfigTag *t = find(n);
  if (t) t->bvalue = v;
}

void Config::setString(const std::string &n, const std::string &v)
{
  ConfigTag *t = find(n);
  if (t) t->value = v;
}

void Config::setList(const std::string &n, const std::vector<std::string> &v)
{
  ConfigTag *t = find(n);
  if (t) t->lvalue = v;
}

bool cfgBool(const char *n)                            { return Config::instance().getBool(n); }
int  cfgInt(const char *n)                             { return Config::instance().getInt(n); }
const std::string &cfgString(const char *n)            { return Config::instance().getString(n); }
const std::string &cfgEnum(const char *n)              { return Config::instance().getEnum(n); }
const std::vector<std::string> &cfgList(const char *n) { return Config::instance().getList(n); }

// ---------------------------------------------------------------------------
// value assignment
// ---------------------------------------------------------------------------

void Config::assign(ConfigTag *t, const std::string &raw, bool append,
                    const std::string &fileName, int line)
{
  const Entry *e = t->decl;
  switch (t->type)
  {
    case Type::Bool:
    {
      if (append) return;   // += is meaningless for a boolean
      bool ok = true;
      std::string v = trimWhiteSpace(raw);
      std::string u = toUpper(v);
      if (u == "YES" || u == "1" || u == "TRUE" || u == "ON" || u.empty()) t->bvalue = true;
      else if (u == "NO" || u == "0" || u == "FALSE" || u == "OFF" || u == "NONE") t->bvalue = false;
      else ok = false;
      if (u.empty()) t->bvalue = (e->numDefaults > 0 && strcmp(e->defaults[0], "YES") == 0);
      if (!ok)
      {
        warn_uncond("argument '%s' for option %s is not a valid boolean value\n",
                    v.c_str(), t->name.c_str());
        const char *d = e->numDefaults > 0 ? e->defaults[0] : "NO";
        errNoPrefix("Using the default: %s!\n", d);
        t->bvalue = strcmp(d, "YES") == 0;
      }
      break;
    }
    case Type::Int:
    {
      if (append) return;
      std::string v = trimWhiteSpace(raw);
      bool ok = !v.empty();
      long n = 0;
      size_t i = 0;
      if (ok)
      {
        char *end = nullptr;
        n = strtol(v.c_str(), &end, 10);
        if (end == nullptr || *end != '\0') ok = false;
      }
      (void)i;
      if (ok && (n < e->minVal || n > e->maxVal)) ok = false;
      if (!ok)
      {
        if (v.empty())
        {
          t->ivalue = e->numDefaults > 0 ? atoi(e->defaults[0]) : 0;
        }
        else
        {
          warn_uncond("argument '%s' for option %s is not a valid number in the range [%d..%d]!\n",
                      v.c_str(), t->name.c_str(), e->minVal, e->maxVal);
          const char *d = e->numDefaults > 0 ? e->defaults[0] : "0";
          errNoPrefix("Using the default: %s!\n", d);
          t->ivalue = atoi(d);
        }
      }
      else
      {
        t->ivalue = static_cast<int>(n);
      }
      break;
    }
    case Type::Enum:
    {
      if (append) return;
      bool wellQuoted = true;
      std::string v = unquoteScalar(raw, wellQuoted);
      if (!wellQuoted)
      {
        warn(fileName, line, "Invalid value for '%s' tag %s: Value '%s' is not properly quoted\n",
             t->name.c_str(), "", trimWhiteSpace(raw).c_str());
      }
      if (v.empty())
      {
        t->value = e->numDefaults > 0 ? e->defaults[0] : "";
        break;
      }
      std::string u = toUpper(v);
      const char *match = nullptr;
      for (int k = 0; k < e->numEnumValues; k++)
      {
        if (toUpper(e->enumValues[k]) == u) { match = e->enumValues[k]; break; }
      }
      if (match)
      {
        t->value = match;
      }
      else
      {
        warn_uncond("argument '%s' for option %s is not a valid enum value\n",
                    v.c_str(), t->name.c_str());
        const char *d = e->numDefaults > 0 ? e->defaults[0] : "";
        errNoPrefix("Using the default: %s!\n", d);
        t->value = d;
      }
      break;
    }
    case Type::String:
    {
      if (append) return;
      bool wellQuoted = true;
      std::string v = unquoteScalar(raw, wellQuoted);
      if (!wellQuoted)
      {
        warnConfigQuote(fileName, line, t->name, trimWhiteSpace(raw), false);
      }
      t->value = v;
      break;
    }
    case Type::List:
    {
      bool wellQuoted = true;
      std::vector<std::string> items = splitList(raw, wellQuoted);
      if (!wellQuoted)
      {
        warnConfigQuote(fileName, line, t->name, trimWhiteSpace(raw), true);
      }
      if (!append) t->lvalue.clear();
      for (const auto &s : items) t->lvalue.push_back(s);
      break;
    }
  }
  t->userSet = true;
}

// ---------------------------------------------------------------------------
// parsing
// ---------------------------------------------------------------------------

bool Config::parse(const std::string &fileName, bool substEnv)
{
  std::string data;
  if (fileName == "-")
  {
    if (!readStdin(data)) return false;
  }
  else
  {
    if (!readFile(fileName, data)) return false;
  }
  return parseString(fileName, data, substEnv);
}

/*! Replace $(VAR) and ${VAR} references by their environment value. */
static std::string substituteEnvVars(const std::string &s)
{
  std::string out;
  for (size_t i = 0; i < s.size(); i++)
  {
    if (s[i] == '$' && i + 1 < s.size() && (s[i + 1] == '(' || s[i + 1] == '{'))
    {
      char close = s[i + 1] == '(' ? ')' : '}';
      size_t j = s.find(close, i + 2);
      if (j != std::string::npos)
      {
        std::string name = s.substr(i + 2, j - i - 2);
        const char *v = getenv(name.c_str());
        if (v) out += v;
        i = j;
        continue;
      }
    }
    out += s[i];
  }
  return out;
}

bool Config::parseString(const std::string &fileName, const std::string &data, bool substEnv)
{
  size_t pos = 0;
  int line = 1;
  const size_t n = data.size();
  while (pos < n)
  {
    // skip leading white space (but not newlines)
    while (pos < n && (data[pos] == ' ' || data[pos] == '\t')) pos++;
    if (pos >= n) break;
    if (data[pos] == '\n') { pos++; line++; continue; }
    if (data[pos] == '\r') { pos++; continue; }
    if (data[pos] == '#')
    {
      while (pos < n && data[pos] != '\n') pos++;
      continue;
    }
    // an @INCLUDE / @INCLUDE_PATH directive
    if (data[pos] == '@')
    {
      size_t s = pos + 1;
      size_t e = s;
      while (e < n && isIdChar(data[e])) e++;
      std::string word = data.substr(s, e - s);
      if (word == "INCLUDE" || word == "INCLUDE_PATH")
      {
        size_t p = e;
        while (p < n && (data[p] == ' ' || data[p] == '\t')) p++;
        if (p < n && data[p] == '=')
        {
          p++;
          std::string raw;
          int startLine = line;
          p = readLogicalLine(data, p, raw, line);
          if (substEnv) raw = substituteEnvVars(raw);
          bool wq = true;
          std::string v = unquoteScalar(raw, wq);
          if (word == "INCLUDE_PATH")
          {
            bool q = true;
            for (const auto &d : splitList(raw, q)) m_includePath.push_back(d);
          }
          else
          {
            std::string found = v;
            struct stat st;
            if (!v.empty() && stat(v.c_str(), &st) != 0)
            {
              found.clear();
              for (const auto &d : m_includePath)
              {
                std::string cand = d + "/" + v;
                if (stat(cand.c_str(), &st) == 0) { found = cand; break; }
              }
            }
            std::string inc;
            if (found.empty() || !readFile(found, inc))
            {
              err("@INCLUDE = %s: not found!\n", v.c_str());
              errNoPrefix("Exiting...\n");
              exit(1);
            }
            parseString(found, inc, substEnv);
          }
          (void)startLine;
          pos = p;
          continue;
        }
      }
      warn_uncond("ignoring unknown character '@' at line %d, file %s\n", line, fileName.c_str());
      pos++;
      continue;
    }
    if (isIdStart(data[pos]))
    {
      size_t s = pos, e = pos;
      while (e < n && isIdChar(data[e])) e++;
      std::string name = data.substr(s, e - s);
      size_t p = e;
      while (p < n && (data[p] == ' ' || data[p] == '\t')) p++;
      bool append = false;
      if (p + 1 < n && data[p] == '+' && data[p + 1] == '=') { append = true; p += 2; }
      else if (p < n && data[p] == '=') { p++; }
      else
      {
        warn_uncond("ignoring unknown tag '%s' at line %d, file %s\n",
                    name.c_str(), line, fileName.c_str());
        pos = e;
        continue;
      }
      std::string raw;
      int startLine = line;
      p = readLogicalLine(data, p, raw, line);
      if (substEnv) raw = substituteEnvVars(raw);
      ConfigTag *t = find(name);
      if (t)
      {
        assign(t, raw, append, fileName, startLine);
      }
      else if (isObsoleteTag(name))
      {
        reportObsoleteTag(name, startLine, fileName);
      }
      else
      {
        warn_uncond("ignoring unsupported tag '%s' at line %d, file %s\n",
                    name.c_str(), startLine, fileName.c_str());
      }
      pos = p;
      continue;
    }
    warn_uncond("ignoring unknown character '%c' at line %d, file %s\n",
                data[pos], line, fileName.c_str());
    pos++;
  }
  return true;
}

// ---------------------------------------------------------------------------
// writing
// ---------------------------------------------------------------------------

/*! Render the value of one tag as it appears after the '=' sign, possibly
 *  spread over several continuation lines.
 */
static std::string renderValue(const ConfigTag &t)
{
  switch (t.type)
  {
    case Type::Bool:   return t.bvalue ? "YES" : "NO";
    case Type::Int:    return std::to_string(t.ivalue);
    case Type::String:
    case Type::Enum:   return quoteConfigValue(t.value);
    case Type::List:
    {
      std::string out;
      for (size_t i = 0; i < t.lvalue.size(); i++)
      {
        if (i > 0) out += " \\\n                         ";
        out += quoteConfigValue(t.lvalue[i]);
      }
      return out;
    }
  }
  return std::string();
}

static void writeTagLine(FILE *f, const ConfigTag &t)
{
  std::string v = renderValue(t);
  if (v.empty()) fprintf(f, "%-23s=\n", t.name.c_str());
  else           fprintf(f, "%-23s= %s\n", t.name.c_str(), v.c_str());
}

static const char *kSeparator =
  "#---------------------------------------------------------------------------";

void Config::writeTemplate(FILE *f, bool shortList, bool updateOnly) const
{
  (void)updateOnly;
  if (shortList)
  {
    fprintf(f, "# Doxyfile %s\n\n", TOOL_VERSION);
  }
  else
  {
    for (int i = 0; i < configdata::numHeaderLines; i++)
    {
      const char *l = configdata::headerLines[i];
      if (*l) fprintf(f, "%s\n", l); else fprintf(f, "\n");
    }
  }
  for (int i = 0; i < configdata::numEntries; i++)
  {
    const Entry &e = configdata::entries[i];
    if (e.kind == Kind::Section)
    {
      if (!shortList) fprintf(f, "\n");
      fprintf(f, "%s\n# %s\n%s\n", kSeparator, e.name, kSeparator);
    }
    else
    {
      const ConfigTag *t = find(e.name);
      if (!t) continue;
      if (!shortList)
      {
        fprintf(f, "\n");
        for (int k = 0; k < e.numDoc; k++)
        {
          if (*e.doc[k]) fprintf(f, "# %s\n", e.doc[k]); else fprintf(f, "#\n");
        }
        fprintf(f, "\n");
      }
      writeTagLine(f, *t);
    }
  }
}

/*! Is the current value of \a t identical to its documented default? */
static bool isDefault(const ConfigTag &t)
{
  const Entry *e = t.decl;
  switch (t.type)
  {
    case Type::Bool:
      return t.bvalue == (e->numDefaults > 0 && strcmp(e->defaults[0], "YES") == 0);
    case Type::Int:
      return t.ivalue == (e->numDefaults > 0 ? atoi(e->defaults[0]) : 0);
    case Type::String:
    case Type::Enum:
      return t.value == (e->numDefaults > 0 ? e->defaults[0] : "");
    case Type::List:
    {
      if (static_cast<int>(t.lvalue.size()) != e->numDefaults) return false;
      for (int k = 0; k < e->numDefaults; k++)
        if (t.lvalue[k] != e->defaults[k]) return false;
      return true;
    }
  }
  return true;
}

void Config::writeDifference(FILE *f) const
{
  fprintf(f, "# Difference with default Doxyfile %s\n", fullVersionString());
  for (int i = 0; i < configdata::numEntries; i++)
  {
    const Entry &e = configdata::entries[i];
    if (e.kind != Kind::Tag) continue;
    const ConfigTag *t = find(e.name);
    if (!t || isDefault(*t)) continue;
    writeTagLine(f, *t);
  }
}

