{
  if (path.empty()) return true;
  std::string acc;
  size_t i = 0;
  if (path[0] == '/') { acc = "/"; i = 1; }
  std::string rest = path.substr(i);
  for (const auto &part : splitString(rest, '/'))
  {
    if (part.empty()) continue;
    if (!acc.empty() && acc.back() != '/') acc += '/';
