std::string trimWhiteSpace(const std::string &s)
{
  size_t b = 0, e = s.size();
  while (b < e && (s[b] == ' ' || s[b] == '\t' || s[b] == '\r' || s[b] == '\n')) b++;
  while (e > b && (s[e - 1] == ' ' || s[e - 1] == '\t' || s[e - 1] == '\r' || s[e - 1] == '\n')) e--;
  return s.substr(b, e - b);
}

std::string toUpper(const std::string &s)
{
  std::string r = s;
  for (auto &c : r) c = static_cast<char>(toupper(static_cast<unsigned char>(c)));
  return r;
}

std::string toLower(const std::string &s)
{
  std::string r = s;
  for (auto &c : r) c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
  return r;
}

bool startsWith(const std::string &s, const std::string &p)
{
  return s.size() >= p.size() && s.compare(0, p.size(), p) == 0;
}

bool endsWith(const std::string &s, const std::string &p)
{
  return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0;
}

std::string replaceAll(std::string s, const std::string &from, const std::string &to)
{
  if (from.empty()) return s;
  size_t p = 0;
  while ((p = s.find(from, p)) != std::string::npos)
  {
    s.replace(p, from.size(), to);
    p += to.size();
  }
  return s;
}

std::vector<std::string> splitString(const std::string &s, char sep)
{
  std::vector<std::string> r;
  size_t start = 0;
  while (true)
  {
    size_t p = s.find(sep, start);
    if (p == std::string::npos) { r.push_back(s.substr(start)); break; }
    r.push_back(s.substr(start, p - start));
    start = p + 1;
  }
