#!/usr/bin/env python3
"""Bundle the files in res/ into a single C++ translation unit with a lookup
table, so the tool has no runtime data dependencies."""
import os, sys

def clit(data):
    out = ['"']
    col = 0
    for b in data:
        if b == 0x0a:   s = '\\n'
        elif b == 0x22: s = '\\"'
        elif b == 0x5c: s = '\\\\'
        elif b == 0x3f: s = '\\?'
        elif 0x20 <= b < 0x7f: s = chr(b)
        else: s = '\\%03o' % b
        out.append(s)
        col += len(s)
        if b == 0x0a and col > 90:
            out.append('"\n  "')
            col = 0
    out.append('"')
    return ''.join(out)

def main(resdir, outfile):
    names = []
    for root, dirs, files in os.walk(resdir):
        dirs.sort()
        for fn in sorted(files):
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, resdir)
            names.append((rel, full))
    with open(outfile, 'w') as f:
        f.write('// Generated by tools/gen_resources.py -- do not edit.\n')
        f.write('#include "resources.h"\n\n#include <cstring>\n\nnamespace {\n\n')
        for i, (rel, full) in enumerate(names):
            data = open(full, 'rb').read()
            f.write('// %s (%d bytes)\nconst char res%d[] =\n  %s;\n\n'
                    % (rel, len(data), i, clit(data)))
        f.write('struct Res { const char *name; const char *data; unsigned len; };\n')
        f.write('const Res g_res[] = {\n')
        for i, (rel, full) in enumerate(names):
            data = open(full, 'rb').read()
            f.write('  { "%s", res%d, %du },\n' % (rel.replace('\\', '/'), i, len(data)))
        f.write('};\nconst unsigned g_numRes = %du;\n\n} // namespace\n\n' % len(names))
        f.write('''
namespace resources {

bool get(const char *name, std::string &out)
{
  for (unsigned i = 0; i < g_numRes; i++)
  {
    if (strcmp(g_res[i].name, name) == 0)
    {
      out.assign(g_res[i].data, g_res[i].len);
      return true;
    }
  }
  return false;
}

std::string getOrEmpty(const char *name)
{
  std::string s;
  get(name, s);
  return s;
}

} // namespace resources
''')
    print('embedded %d resources' % len(names))

main(sys.argv[1], sys.argv[2])
