{
  const char *progName = argv[0];
  std::string configName;
  bool genConfig = false, updateConfig = false, shortList = false;
  bool compareConfig = false, substEnv = true;
  bool quietFlag = false;
  int  optInd = 1;

  Config &cfg = Config::instance();
  cfg.loadDefaults();

  // ---- command line ---------------------------------------------------
  while (optInd < argc && argv[optInd][0] == '-' && argv[optInd][1] != '\0')
  {
    const char *opt = argv[optInd];
    if (strcmp(opt, "-g") == 0)
    {
      genConfig = true;
      optInd++;
      if (optInd < argc && argv[optInd][0] != '-') configName = argv[optInd++];
      else if (optInd < argc && strcmp(argv[optInd], "-") == 0) configName = argv[optInd++];
      continue;
    }
    if (strcmp(opt, "-u") == 0)
    {
      updateConfig = true;
      optInd++;
      if (optInd < argc && (argv[optInd][0] != '-' || strcmp(argv[optInd], "-") == 0))
        configName = argv[optInd++];
      continue;
    }
    if (strcmp(opt, "-s") == 0) { shortList = true; optInd++; continue; }
    if (strcmp(opt, "-q") == 0) { quietFlag = true; optInd++; continue; }
    if (strcmp(opt, "-x") == 0 || strcmp(opt, "-x_noenv") == 0)
    {
      compareConfig = true;
      substEnv = (strcmp(opt, "-x") == 0);
      optInd++;
      if (optInd < argc && (argv[optInd][0] != '-' || strcmp(argv[optInd], "-") == 0))
        configName = argv[optInd++];
      continue;
    }
    if (strcmp(opt, "-l") == 0)
    {
      optInd++;
      std::string name = "DoxygenLayout.xml";
      if (optInd < argc) name = argv[optInd++];
      writeLayout(name);
      return 0;
    }
    if (strcmp(opt, "-e") == 0)
    {
      optInd++;
      if (optInd >= argc) term("option \"-e\" is missing format specifier rtf.\n");
      if (strcmp(argv[optInd], "rtf") != 0) term("option \"-e\" has invalid format specifier.\n");
      optInd++;
      if (optInd >= argc) term("option \"-e rtf\" is missing an extensions file name\n");
      writeRtfExtensions(argv[optInd]);
      return 0;
    }
    if (strcmp(opt, "-f") == 0)
    {
      optInd++;
      if (optInd >= argc) term("option \"-f\" is missing list specifier.\n");
      if (strcmp(argv[optInd], "emoji") != 0) term("option \"-f\" has invalid list specifier.\n");
      optInd++;
      if (optInd >= argc) term("option \"-f emoji\" is missing an output file name\n");
      writeEmojiList(argv[optInd]);
      return 0;
    }
    if (strcmp(opt, "-w") == 0)
    {
      optInd++;
      if (optInd >= argc) term("option \"-w\" is missing format specifier rtf, html or latex\n");
      std::string fmt = argv[optInd++];
      if (fmt == "rtf")
      {
        if (optInd >= argc) term("option \"-w rtf\" is missing a style sheet file name\n");
        writeRtfStyleSheet(argv[optInd]);
        return 0;
