      {
        if (optInd + 2 >= argc)
          term("option \"-w %s\" does not have enough arguments\n", fmt.c_str());
        std::string hdr = argv[optInd++];
        std::string ftr = argv[optInd++];
        std::string sty = argv[optInd++];
        if (optInd < argc)
        {
