      addDebugLevel(argv[optInd++]);
      continue;
    }
    if (strcmp(opt, "-m") == 0) { optInd++; continue; }
    if (strcmp(opt, "-b") == 0) { setvbuf(stdout, nullptr, _IONBF, 0); optInd++; continue; }
    if (strcmp(opt, "-v") == 0) { printf("%s\n", fullVersionString()); return 0; }
    if (strcmp(opt, "-V") == 0)
    {
      printf("%s\n", fullVersionString());
      printf("    with sqlite3 %s.\n", SQLITE3_VERSION);
      return 0;
    }
