      if (configName != "Doxyfile" && configName != "doxyfile")
        msg("  doxygen %s\n\n", configName.c_str());
      else
        msg("  doxygen\n\n");
      msg("to generate the documentation for your project\n\n");
    }
    return 0;
  }

  if (configName.empty()) configName = "Doxyfile";

  if (updateConfig)
  {
    setObsoleteRemovedMode(true);
    if (!cfg.parse(configName, true))
      term("configuration file %s not found!\n", configName.c_str());
    if (configName != "-")
    {
      std::string data;
      readFile(configName, data);
      writeFile(configName + ".bak", data);
    }
    FILE *f = openForWrite(configName);
    cfg.writeTemplate(f, shortList, true);
    closeIfFile(f);
    if (configName != "-") msg("\n\nConfiguration file '%s' updated.\n\n", configName.c_str());
    return 0;
  }

  if (compareConfig)
  {
    if (!cfg.parse(configName, substEnv))
      term("configuration file %s not found!\n", configName.c_str());
    cfg.writeDifference(stdout);
    return 0;
  }

  // ---- a documentation run --------------------------------------------
  if (configName != "-" && !fileExists(configName))
  {
    err("configuration file %s not found!\n", configName.c_str());
    usage(progName);
    return 1;
  }
  if (!cfg.parse(configName, true))
  {
    err("configuration file %s not found!\n", configName.c_str());
    usage(progName);
    return 1;
  }
  if (quietFlag) cfg.setBool("QUIET", true);
  return generateDocumentation();
}

