#include "emoji.h"
#include "resources.h"

#include <vector>

/*! The emoji names live in an embedded resource so the list stays in the exact
 *  order used when reporting them.
 */
static const std::vector<std::string> &emojiNames()
{
  static std::vector<std::string> names;
  if (names.empty())
  {
    std::string data = resources::getOrEmpty("emoji_names.txt");
    size_t start = 0;
    while (start < data.size())
    {
      size_t nl = data.find('\n', start);
      if (nl == std::string::npos) nl = data.size();
      if (nl > start) names.push_back(data.substr(start, nl - start));
      start = nl + 1;
    }
  }
  return names;
}

void writeEmojiNames(FILE *f)
{
  for (const auto &n : emojiNames()) fprintf(f, "%s\n", n.c_str());
}

int numEmojis() { return static_cast<int>(emojiNames().size()); }

