bool debugEnabled(const std::string &level)  { return g_debugLevels.count(toLower(level)) > 0; }

// ---------------------------------------------------------------------------
// -w templates
// ---------------------------------------------------------------------------

static void dumpResource(const std::string &fileName, const char *resName)
{
  std::string s = resources::getOrEmpty(resName);
  if (fileName == "-")
  {
    fwrite(s.data(), 1, s.size(), stdout);
    return;
  }
  FILE *f = fopen(fileName.c_str(), "w");
  if (!f) term("Cannot open file %s for writing\n", fileName.c_str());
  fwrite(s.data(), 1, s.size(), f);
  fclose(f);
}

