import re
body = open('body.css').read()
light = {}
for l in open('lightvars.txt'):
    m = re.match(r'^--([a-z0-9-]+):\s*(.*);\s*$', l.strip())
    if m: light[m.group(1)] = m.group(2)
def subst(txt, table):
    def rep(m):
        return table.get(m.group(1), 'var(--%s)'%m.group(1))
    return re.sub(r'var\(--([a-z0-9-]+)\)', rep, txt)
out = subst(body, light)
open('light_pred.css','w').write(out)
EOF
